fun main() {
    val nums = listOf(5, 3, 8, 1)
    println(nums.sorted())
    println(nums.filter { it > 2 })
    val ages = mapOf("Ann" to 30, "Bob" to 25)
    for ((name, age) in ages) println("$name is $age")
}

fun area(width: Int, height: Int = 1): Int = width * height

fun main() {
    println(area(3, 4))
    println(area(5))
}

fun main() {
    var a = 0
    var b = 1
    val result = mutableListOf<Int>()
    repeat(10) {
        result.add(a)
        val next = a + b
        a = b
        b = next
    }
    println(result)
}

